int load_tags(sqlite3 *db, const char **tags, int max) {
  sqlite3_stmt *stmt = NULL;
  int n = 0;
  if (sqlite3_prepare_v2(db, "SELECT name FROM tags ORDER BY name", -1, &stmt, NULL) != SQLITE_OK) {
    return -1;
  }
  while (n < max && sqlite3_step(stmt) == SQLITE_ROW) {
    tags[n++] = (const char *)sqlite3_column_text(stmt, 0);
  }
  sqlite3_finalize(stmt);
  return n;
}

