#include <stdlib.h>
#include <string.h>
#include <sqlite3.h>

int load_tags(sqlite3 *db, char **tags, int max) {
  sqlite3_stmt *stmt = NULL;
  int n = 0;
  if (sqlite3_prepare_v2(db, "SELECT name FROM tags ORDER BY name", -1, &stmt, NULL) != SQLITE_OK) {
    return -1;
  }
  while (n < max && sqlite3_step(stmt) == SQLITE_ROW) {
    const char *name = (const char *)sqlite3_column_text(stmt, 0);
    char *copy = strdup(name);
    if (copy == NULL) break;
    tags[n++] = copy;
  }
  sqlite3_finalize(stmt);
  return n;
}

void free_tags(char **tags, int n) {
  for (int i = 0; i < n; i++) free(tags[i]);
}
